-- Production lqvuqamzmchepgxkftcw READ ONLY; preserve every original raw ledger row.
-- Raw JSONB-row SHA distinguishes CRLF from LF; does not fill missing Source.
begin transaction isolation level repeatable read read only;set local statement_timeout='15s';
select jsonb_build_object('observedAt',clock_timestamp(),'allLedgerCount',(select count(*) from supabase_migrations.schema_migrations),'allLedgerHead',(select max(version) from supabase_migrations.schema_migrations),'originalRows',(select jsonb_agg(jsonb_build_object('version',m.version,'rawRowSha256',encode(sha256(convert_to(to_jsonb(m)::text,'UTF8')),'hex')) order by m.version) from supabase_migrations.schema_migrations m where version=any(array['001','002','003','004','005','006','007','008','009','010','011','012','013','014','015','016','017','018','019','020','021','022','023','024','20260708063744','20260710125337','20260712033758','20260809090000','20260809091000','20260811124500','20260811133000','20260811150000','20260819134935','20261022090000','20261022100000','20261022110000','20261022120000','20261022162015','20261023120000','20261024054121','20261024063828','20261024112902','20261026120000','20261027140044','20261027145613','20261027152539','20261028104333','20261031003000']))) preservation;
commit;
